<?php
namespace App\Http\Controllers\Pelanggan;
use App\Http\Controllers\Controller;use App\Http\Requests\StoreBookingServisRequest;use App\Models\{BookingServis,JenisServis};use App\Services\{BookingServisService,ServicePersonnelAvailabilityService,ServiceSchedulingService,VehicleGalleryService,VerifiedCarOwnershipService};use Illuminate\Http\Request;use Throwable;
class BookingServisController extends Controller {
 private function customer(Request $r){$p=$r->user()->pelanggan;abort_unless($p,404);return $p;}
 public function index(Request $r){$rows=BookingServis::with(['kendaraan','jenisServis'])->where('id_pelanggan',$this->customer($r)->id_pelanggan)->latest('tanggal')->latest('jam')->paginate(15);return view('pelanggan.booking-servis.index',compact('rows'));}
 public function create(Request $r,VehicleGalleryService $gallery,VerifiedCarOwnershipService $ownership){$p=$this->customer($r);$vehicles=$p->kendaraan()->where('status','aktif')->with(['penjualan.mobil','pesanan'])->orderBy('merk')->orderBy('model')->get();$selectedVehicleId=(int)$r->integer('kendaraan');abort_if($selectedVehicleId && !$vehicles->contains('id_kendaraan_pelanggan',$selectedVehicleId),404);$vehicles->each(function($vehicle)use($gallery,$ownership,$p):void{$mobil=$vehicle->penjualan?->mobil;$purchasedColor=$vehicle->pesanan?->snapshot_warna ?: $vehicle->warna;$selected=$mobil?$gallery->forColor($mobil,$purchasedColor):[];if(!$selected&&!$purchasedColor&&$mobil)$selected=$gallery->for($mobil)[$gallery->defaultColor($mobil)]??[];$vehicle->setAttribute('booking_image',$selected['images'][0]['src']??asset('assets/images/hero/yza-hero-reference-v3.png'));$vehicle->setAttribute('is_verified_ownership',$ownership->vehicleBelongsToVerifiedPurchase((int)$p->id_pelanggan,(int)$vehicle->id_kendaraan_pelanggan));});$types=JenisServis::where('status','aktif')->orderBy('nama_servis')->get();return view('pelanggan.booking-servis.create',compact('vehicles','types','selectedVehicleId'));}
 public function store(StoreBookingServisRequest $req,BookingServisService $svc){try{$d=$req->validated();$b=$svc->create($this->customer($req)->id_pelanggan,(int)$d['id_kendaraan_pelanggan'],(int)$d['id_jenis_servis'],$d['tanggal'],$d['jam'],$d['keluhan']??null,$d['catatan']??null,isset($d['id_preferred_petugas'])?(int)$d['id_preferred_petugas']:null);return redirect()->route('pelanggan.booking-servis.show',$b)->with('success','Booking servis berhasil diajukan.');}catch(Throwable $e){$message=str_contains($e->getMessage(),'Teknisi tidak aktif')?'Teknisi pilihan Anda sudah tidak tersedia pada jadwal tersebut. Silakan pilih teknisi lain atau lanjutkan tanpa preferensi.':$e->getMessage();return back()->withInput()->withErrors($message);}}
 public function availability(Request $r,ServiceSchedulingService $s){$d=$r->validate(['date'=>'nullable|required_without:month|date_format:Y-m-d','month'=>'nullable|required_without:date|date_format:Y-m','jenis_servis_id'=>'required|integer|exists:jenis_servis,id_jenis_servis']);return response()->json(isset($d['month'])?$s->monthAvailability($d['month'],(int)$d['jenis_servis_id']):$s->availability($d['date'],(int)$d['jenis_servis_id']));}
 public function technicians(Request $r,ServicePersonnelAvailabilityService $s){$d=$r->validate(['date'=>'required|date_format:Y-m-d','time'=>'required|date_format:H:i','jenis_servis_id'=>'required|integer|exists:jenis_servis,id_jenis_servis']);return response()->json(['date'=>$d['date'],'time'=>$d['time'],'jenis_servis_id'=>(int)$d['jenis_servis_id'],'technicians'=>$s->technicians($d['date'],$d['time'],(int)$d['jenis_servis_id'])]);}
 public function show(Request $r,BookingServis $booking_servis){abort_unless((int)$booking_servis->id_pelanggan===(int)$this->customer($r)->id_pelanggan,403);$booking_servis->load(['kendaraan','jenisServis','preferredPetugas']);return view('pelanggan.booking-servis.show',compact('booking_servis'));}
 public function cancel(Request $r,BookingServis $booking_servis,BookingServisService $svc){abort_unless((int)$booking_servis->id_pelanggan===(int)$this->customer($r)->id_pelanggan,403);try{$svc->cancel($booking_servis->id_booking_servis,$this->customer($r)->id_pelanggan);return back()->with('success','Booking servis dibatalkan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
}
